const body = $input.first().json.body || {};
for (const f of ['tenant_slug', 'lead_id', 'sequence_id']) {
  if (!body[f]) throw new Error(`${f} is required`);
}
return [{ json: { tenant_slug: String(body.tenant_slug).trim(), lead_id: body.lead_id, sequence_id: body.sequence_id } }];

const r = $input.first().json;
if (!r.tenant_id) return [{ json: { valid: false, status: 404, error: 'tenant not found' } }];
if (!r.lead_id) return [{ json: { valid: false, status: 404, error: 'lead not found for this tenant' } }];
if (!r.sequence_id) return [{ json: { valid: false, status: 404, error: 'sequence not found for this tenant, or not active' } }];
if (r.already_running) return [{ json: { valid: false, status: 409, error: 'a run is already active for this lead + sequence' } }];

const steps = r.steps || [];
if (!Array.isArray(steps) || steps.length === 0) {
  return [{ json: { valid: false, status: 422, error: 'sequence has no steps' } }];
}

return [{
  json: {
    valid: true,
    tenant_id: r.tenant_id,
    lead_id: r.lead_id,
    sequence_id: r.sequence_id,
    first_step_day_offset: steps[0].day_offset ?? 0,
  }
}];

